cat > Program.cs <<'EOF'
using System.Reflection;
var paths = Directory.GetFiles(System.Runtime.InteropServices.RuntimeEnvironment.GetRuntimeDirectory(), "*.dll").ToList();
paths.Add(args[0]);
using var mlc = new MetadataLoadContext(new PathAssemblyResolver(paths));
var asm = mlc.LoadFromAssemblyPath(args[0]);
Console.WriteLine(asm.FullName);
foreach (var r in asm.GetReferencedAssemblies()) Console.WriteLine("ref " + r);
foreach (var t in asm.GetTypes()) {
  Console.WriteLine($"{(t.IsPublic?"public ":"")}{t.FullName} : {t.BaseType?.Name} [{string.Join(",", t.GetInterfaces().Select(i=>i.Name))}]");
  foreach (var m in t.GetMembers(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static|BindingFlags.DeclaredOnly)) Console.WriteLine("   " + m);
}
EOF
