                var m => m,
            })
            .Select(g => $"  {g.Count(),6} × {g.Key}");
        Assert.Fail($"{all.Count} écarts avec la spec.\\nPar catégorie :\\n{string.Join("\\n", categories)}\\n"
            + $"Exemples :\\n{string.Join("\\n", all.Take(15))}");
    }

'''
